using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class ActorInspectorOperations
{
    public Resource? resolve_object(Resource? reference){if(reference==null)return null;if(reference.Get("object_type").AsString() is "powder_material" or "destruction_material" or "destruction_region" or "debris_vfx")return _animation.resolve_reference(reference);string path=reference.Get("asset_id").AsString();Resource? result=reference.Get("source").AsInt32()==1?(path.Length>0?ResourceLoader.Load(path,"",ResourceLoader.CacheMode.Ignore):null):reference.Get("embedded").As<Resource>();return ActorDataOperations.ScriptIs(result,"res://scripts/actors/core/actor_object_data.gd")&&result!.Get("type_id").AsString()==reference.Get("object_type").AsString()?result:null;}
    private Settings BindingCurrent(Control owner,string id,string[] path,Resource? origin){var actor=_timeline.actor_for_id(Ui<RefCounted>(owner,"model"),id);if(actor==null&&GodotObject.IsInstanceValid(origin)&&origin!.Get("id").AsString()==id)actor=origin;if(actor==null)return new Settings();var value=_animation.value_at_path(actor,path);var resource=value.VariantType==Variant.Type.Object?value.AsGodotObject() as Resource:null;if(ActorDataOperations.ScriptIs(resource,"res://scripts/actors/core/actor_object_reference.gd"))resource=_animation.resolve_reference(resource!);if(!ActorDataOperations.ScriptIs(resource,"res://scripts/actors/core/actor_object_data.gd"))return new Settings();var definition=_definitions.get_object_definition(Ui<RefCounted>(owner,"registry"),resource!.Get("type_id").AsStringName());return definition!=null?new Settings{["actor"]=actor,["object"]=resource,["definition"]=definition}:new Settings();}
    public Settings read_shader_binding(Control owner,string id,string[] path,Resource? origin){var current=BindingCurrent(owner,id,path,origin);if(current.Count==0)return new Settings();var definition=current["definition"].As<Resource>();var property=_definitions.find_property(definition,"uniforms");if(property==null)return new Settings();var values=animated_object_value(owner,current["actor"].As<Resource>(),current["object"].As<Resource>(),definition,property);return values.VariantType==Variant.Type.Dictionary?values.AsGodotDictionary().Duplicate(true):new Settings();}
    public void write_shader_binding(Control owner,string id,string[] path,Resource? origin,UndoRedo history,StringName name,Variant value,string mode,Variant original){var current=BindingCurrent(owner,id,path,origin);if(current.Count==0)return;var model=Ui<RefCounted>(owner,"model");var actor=current["actor"].As<Resource>();var data=current["object"].As<Resource>();var definition=current["definition"].As<Resource>();if(model.Get("actors").AsGodotArray().Contains(actor))_timeline.edit_shader_uniform(model,actor,data,definition,name,value,mode,original);else edit_detached_shader_uniform(owner,data,definition,history,name,value,mode,original);var selected=owner.Get("_actor").As<Resource>();var resource=value.VariantType==Variant.Type.Object?value.AsGodotObject() as Resource:null;if(selected!=null&&selected.Get("id").AsString()==id&&(value.VariantType is Variant.Type.String or Variant.Type.Nil||resource is Texture2D||ActorDataOperations.ScriptIs(resource,"res://scripts/actors/core/actor_object_reference.gd")||ActorDataOperations.ScriptIs(resource,"res://scripts/actors/core/actor_object_data.gd")))owner.Call("_queue_rebuild_selected");}
    public void set_detached_object_property(Resource data,StringName key,Variant value){_data.set_value(data,key,_data.copy_value(value));if(data.ResourcePath.Length>0)ResourceSaver.Save(data,data.ResourcePath);}
    public void edit_detached_shader_uniform(Control owner,Resource data,Resource definition,UndoRedo history,StringName name,Variant value,string mode,Variant original){var property=_definitions.find_property(definition,"uniforms");if(property==null)return;var before=_definitions.value_for(data,property).AsGodotDictionary().Duplicate(true);var after=before.Duplicate(true);after[name]=_data.copy_value(value);if(mode=="preview"){set_detached_object_property(data,"uniforms",after);return;}if(mode=="commit"&&original.VariantType==Variant.Type.Dictionary)foreach(var entry in original.AsGodotDictionary())before[entry.Key]=_data.copy_value(entry.Value);if(same_value(before,after))return;var action=new InspectorFilePropertyAction(Ui<RefCounted>(owner,"model"),data,data,data,"uniforms",before,after,false);history.CreateAction("Change "+property.Get("label").AsString());history.AddDoMethod(new Callable(action,nameof(InspectorFilePropertyAction.restore_after)));history.AddUndoMethod(new Callable(action,nameof(InspectorFilePropertyAction.restore_before)));history.AddDoReference(action);history.CommitAction();}
    public void write_natural_material(Control owner,Resource? actor,Resource data,Resource definition,Resource property,Resource? saveOwner,Settings value,string mode,Settings original){var model=Ui<RefCounted>(owner,"model");var key=property.Get("id").AsStringName();if(actor!=null){if(mode=="preview")_timeline.preview_object_property(model,actor,data,definition,key,value);else _timeline.commit_object_property_preview(model,actor,data,definition,key,original,value);return;}var target=data.ResourcePath.Length>0?data:saveOwner;if(mode=="preview"){_data.set_value(data,key,value.Duplicate(true));if(target!=null&&target.ResourcePath.Length>0)ResourceSaver.Save(target,target.ResourcePath);model.EmitSignal("changed");}else if(!same_value(value,original)){var action=new InspectorFilePropertyAction(model,data,saveOwner??data,target??data,key,original.Duplicate(true),value.Duplicate(true));var history=model.Get("history").As<UndoRedo>();history.CreateAction("Change Natural Material");history.AddDoMethod(new Callable(action,nameof(InspectorFilePropertyAction.restore_after)));history.AddUndoMethod(new Callable(action,nameof(InspectorFilePropertyAction.restore_before)));history.AddDoReference(action);history.CommitAction();}}
}
